import z from "zod";

export const placePathSchema = z
  .string()
  .min(1, "Path is required")
  .max(200, "Path is too long")
  .regex(
    /^[a-z0-9-]+(?:\/[a-z0-9-]+)*$/,
    "Path can only contain lowercase letters, numbers, hyphens, and forward slashes",
  );

export const placeSlugSchema = z
  .string()
  .min(1, "Place slug is required")
  .max(100, "Slug is too long")
  .regex(
    /^[a-z0-9-]+$/,
    "Slug can only contain lowercase letters, numbers, and hyphens",
  );

export const placeReviewsSchema = z.object({
  page: z.coerce.number().min(1).default(1),
  limit: z.coerce.number().min(1).default(6),
  placeId: z.uuid(),
});

export const nearbyPlacesSchema = z.object({
  lat: z.coerce.number().min(-90).max(90),
  lng: z.coerce.number().min(-180).max(180),
  radius: z.coerce.number().min(1).max(1000),
  limit: z.coerce.number().min(1).max(100),
});

export const trendingPlacesSchema = z.object({
  limit: z.coerce.number().min(1).max(20).default(6),
});

export const searchPlacesSchema = z.object({
  q: z.string().min(1).max(100),
});

export const SUGGESTABLE_FIELDS = [
  "name",
  "address",
  "phone",
  "email",
  "website",
  "hours",
  "description",
  "dogRules",
  "dogAmenities",
  "offLeadAllowed",
  "waterAvailable",
] as const;

export type SuggestableField = (typeof SUGGESTABLE_FIELDS)[number];

export const suggestEditSchema = z.object({
  placeId: z.uuid(),
  field: z.enum(SUGGESTABLE_FIELDS),
  suggestedValue: z.union([
    z.string().min(1).max(2000),
    z.boolean(),
    z.array(z.string().min(1).max(200)),
    z.record(z.string(), z.any()),
  ]),
  notes: z.string().max(500).optional(),
});

export const explorePlacesSchema = z.object({
  swLat: z.coerce.number().min(-90).max(90),
  swLng: z.coerce.number().min(-180).max(180),
  neLat: z.coerce.number().min(-90).max(90),
  neLng: z.coerce.number().min(-180).max(180),
  types: z
    .string()
    .optional()
    .transform((v) => (v ? v.split(",") : undefined)),
  rating: z.coerce.number().min(1).max(5).optional(),
  distance: z.coerce.number().min(1).max(1000).optional(),
  minLength: z.coerce.number().min(0).optional(),
  maxLength: z.coerce.number().min(0).optional(),
  difficulty: z.enum(["beginner", "intermediate", "advanced"]).optional(),
});
